import{elements}from"./elements.min.js";import{state}from"./state.min.js";import{playPauseHandler,nextHandler,prevHandler}from"./playback.min.js";import{handleFileUpload,togglePlaylistVisibility,handleSelectAll,handleDeleteSelected,playItem,toggleSelection,cleanupMemory}from"./playlist.min.js";import{initializeSortButton,cycleSortOrder,cycleSortOrderReverse}from"./sorting.min.js";import{renderPlayList}from"./ui.min.js";function initializeEventListeners(){elements.playPauseBtn.addEventListener("click",playPauseHandler);elements.prevBtn.addEventListener("click",prevHandler);elements.nextBtn.addEventListener("click",nextHandler);window.addEventListener("keydown",(function(e){if(e.key==="ArrowRight"||e.key==="MediaTrackNext"){e.preventDefault();nextHandler()}else if(e.key==="ArrowLeft"||e.key==="MediaTrackPrevious"){e.preventDefault();prevHandler()}else if(e.key===" "||e.key==="MediaPlayPause"){e.preventDefault();playPauseHandler()}}));if("mediaSession"in navigator){navigator.mediaSession.setActionHandler("previoustrack",prevHandler);navigator.mediaSession.setActionHandler("nexttrack",nextHandler);navigator.mediaSession.setActionHandler("play",(()=>{state.audio.play();elements.playPauseBtn.textContent="⏸";elements.playPauseBtn.setAttribute("aria-label","Pause")}));navigator.mediaSession.setActionHandler("pause",(()=>{state.audio.pause();elements.playPauseBtn.textContent="▶";elements.playPauseBtn.setAttribute("aria-label","Play")}))}elements.uploadBtn.addEventListener("click",(()=>elements.fileUpload.click()));elements.fileUpload.addEventListener("change",handleFileUpload);elements.selectAllBtn.addEventListener("click",handleSelectAll);elements.deleteSelectedBtn.addEventListener("click",handleDeleteSelected);elements.togglePlaylistBtn.addEventListener("click",togglePlaylistVisibility);elements.sortControlBtn.addEventListener("click",(function(e){if(e.shiftKey){cycleSortOrderReverse(e.target)}else{cycleSortOrder(e.target)}}));elements.sortControlBtn.addEventListener("keydown",(function(e){if(e.shiftKey&&e.key==="Enter"){e.preventDefault();cycleSortOrderReverse(e.target)}}));if("onlowmemory"in window){window.addEventListener("lowmemory",(()=>{console.log("Low memory condition detected");cleanupMemory()}))}if(window.chrome&&"ChromePressure"in window.chrome){window.addEventListener("pressurelevel",(e=>{if(e.level==="critical"){console.log("Memory pressure critical");cleanupMemory()}}))}initializeSortButton(elements.sortControlBtn);initializePlaylistEvents();initializeGestures();initializeDraggableControls()}function initializeGestures(){const hammer=new Hammer.Manager(document.body,{recognizers:[[Hammer.Swipe,{direction:Hammer.DIRECTION_HORIZONTAL}],[Hammer.Tap,{event:"singletap",taps:1,interval:250,time:250,threshold:9}]]});hammer.get("swipe").recognizeWith("singletap");hammer.get("singletap").requireFailure("swipe");hammer.on("singletap",(e=>{if(!e.target.closest("button, input, a, li")){playPauseHandler()}}));hammer.on("swiperight",nextHandler);hammer.on("swipeleft",prevHandler)}function initializePlaylistEvents(){elements.playList.addEventListener("mousedown",(function(e){const li=e.target.closest("li");if(!li)return;const index=parseInt(li.dataset.index);if(e.ctrlKey||e.metaKey||e.shiftKey){e.preventDefault()}}));elements.playList.addEventListener("click",(function(e){const li=e.target.closest("li");if(!li)return;const index=parseInt(li.dataset.index);if(isNaN(index))return;if(e.button!==0)return;if(e.ctrlKey||e.metaKey||e.shiftKey){toggleSelection(index)}else{playItem(index)}}));let touchTimer;let touchStartTime;elements.playList.addEventListener("touchstart",(function(e){const li=e.target.closest("li");if(!li)return;const index=parseInt(li.dataset.index);touchStartTime=Date.now();touchTimer=setTimeout((()=>{toggleSelection(index);li.classList.add("long-press")}),500)}),{passive:true});elements.playList.addEventListener("touchend",(function(e){const li=e.target.closest("li");if(!li)return;clearTimeout(touchTimer);const index=parseInt(li.dataset.index);if(!li.classList.contains("long-press")){if(Date.now()-touchStartTime<200){e.preventDefault();playItem(index)}}li.classList.remove("long-press")}),{passive:false});let scrollTimeout;const scrollHandler=()=>{if(scrollTimeout)cancelAnimationFrame(scrollTimeout);scrollTimeout=requestAnimationFrame((()=>{renderPlayList()}))};elements.playList.addEventListener("scroll",scrollHandler);elements.playList.addEventListener("touchmove",scrollHandler,{passive:true})}function initializeDraggableControls(){const circularControls=document.querySelector(".circular-controls");circularControls.style.position="absolute";circularControls.style.zIndex="1000";const dragHandle=document.createElement("div");dragHandle.className="drag-handle";dragHandle.innerHTML="⋮⋮";circularControls.appendChild(dragHandle);setControlsPosition(state.controlsPosition.xOffset,state.controlsPosition.yOffset,circularControls);circularControls.addEventListener("mousedown",dragStart);document.addEventListener("mouseup",dragEnd);document.addEventListener("mousemove",drag);circularControls.addEventListener("touchstart",dragStart,{passive:false});document.addEventListener("touchend",dragEnd,{passive:true});document.addEventListener("touchmove",drag,{passive:false});function dragStart(e){if(e.target.classList.contains("control-btn")||e.target.closest(".control-btn")){return}e.preventDefault();if(e.type==="touchstart"){state.controlsPosition.initialX=e.touches[0].clientX-state.controlsPosition.xOffset;state.controlsPosition.initialY=e.touches[0].clientY-state.controlsPosition.yOffset}else{state.controlsPosition.initialX=e.clientX-state.controlsPosition.xOffset;state.controlsPosition.initialY=e.clientY-state.controlsPosition.yOffset}state.controlsPosition.isDragging=true;circularControls.style.cursor="grabbing";circularControls.style.boxShadow="2px 2px 20px 5px #530844"}function drag(e){if(state.controlsPosition.isDragging){e.preventDefault();let currentX,currentY;if(e.type==="touchmove"){currentX=e.touches[0].clientX-state.controlsPosition.initialX;currentY=e.touches[0].clientY-state.controlsPosition.initialY}else{currentX=e.clientX-state.controlsPosition.initialX;currentY=e.clientY-state.controlsPosition.initialY}state.controlsPosition.xOffset=currentX;state.controlsPosition.yOffset=currentY;setControlsPosition(currentX,currentY,circularControls)}}function dragEnd(e){if(!state.controlsPosition.isDragging)return;state.controlsPosition.isDragging=false;circularControls.style.cursor="grab";circularControls.style.boxShadow="2px 2px 0px 0px #f70a0a80,"+"2px 2px 20px 5px #530844";localStorage.setItem("controlsX",state.controlsPosition.xOffset);localStorage.setItem("controlsY",state.controlsPosition.yOffset)}}function setControlsPosition(xPos,yPos,el){const rect=el.getBoundingClientRect();const viewportWidth=window.innerWidth;const viewportHeight=window.innerHeight;if(xPos<-rect.width/2)xPos=-rect.width/2;if(yPos<0)yPos=0;if(xPos>viewportWidth-rect.width/2)xPos=viewportWidth-rect.width/2;if(yPos>viewportHeight-rect.height)yPos=viewportHeight-rect.height;el.style.transform=`translate(${xPos}px, ${yPos}px)`}export{initializeEventListeners};